// ======================================================
// ROYAL EXPRESS C.A. - PREPARAR PARÁMETROS (CON MENÚ DE REINICIO POR FAMILIAS)
// ======================================================
var MESES_NOMBRE = ['ENERO','FEBRERO','MARZO','ABRIL','MAYO','JUNIO','JULIO','AGOSTO','SEPTIEMBRE','OCTUBRE','NOVIEMBRE','DICIEMBRE'];

function pad2(n) { return (n < 10 ? '0' : '') + n; }

function formatFechaDDMMYY(fecha) {
  return pad2(fecha.getDate()) + '-' + pad2(fecha.getMonth() + 1) + '-' + String(fecha.getFullYear()).slice(-2);
}

var ANCLA_SEMANA1 = new Date(2026, 0, 5);

function calcularNumeroSemana(fecha) {
  var diffMs = fecha.getTime() - ANCLA_SEMANA1.getTime();
  var diffDias = Math.floor(diffMs / 86400000);
  var numero = Math.floor(diffDias / 7) + 1;
  if (numero < 0) numero = 0;
  if (numero > 52) numero = 52;
  return numero;
}

function calcularRangoSemana(numeroSemana) {
  var inicio = new Date(ANCLA_SEMANA1.getTime() + (numeroSemana - 1) * 7 * 86400000);
  var fin = new Date(inicio.getTime() + 6 * 86400000);
  return { inicio: inicio, fin: fin };
}

function mesMayoritarioDeSemana(numeroSemana) {
  var rango = calcularRangoSemana(numeroSemana);
  var conteo = {};
  for (var i = 0; i < 7; i++) {
    var d = new Date(rango.inicio.getTime() + i * 86400000);
    var key = d.getFullYear() + '-' + d.getMonth();
    conteo[key] = (conteo[key] || 0) + 1;
  }
  var mejorKey = null, mejorCount = -1;
  Object.keys(conteo).forEach(function(k) {
    if (conteo[k] > mejorCount) { mejorCount = conteo[k]; mejorKey = k; }
  });
  var partes = mejorKey.split('-');
  return { anio: parseInt(partes[0], 10), mes: parseInt(partes[1], 10) };
}

function semanasDelMes(mesIndex, anio, semanaCercana) {
  var lista = [];
  var inicioScan = Math.max(1, semanaCercana - 7);
  var finScan = Math.min(52, semanaCercana + 7);
  for (var s = inicioScan; s <= finScan; s++) {
    var m = mesMayoritarioDeSemana(s);
    if (m.mes === mesIndex && m.anio === anio) lista.push(s);
  }
  lista.sort(function(a, b) { return a - b; });
  return lista;
}

var inputItems = $input.all();
var nodeInput = inputItems.length ? inputItems[0].json : {};

var triggerJson = {};
try { triggerJson = $('Telegram Trigger').first().json; } catch(e) {}

var item = (triggerJson && (triggerJson.message || triggerJson.callback_query)) ? triggerJson : nodeInput;
var hoy = new Date();

var modo = nodeInput.modo || 'reporte_semana';
var modoForzado = (nodeInput.modo === 'alerta_2h' || nodeInput.modo === 'reporte_diario_auto');

var textoMensaje = '';
var chatId = '5016875501';
var fromName = 'Usuario';

if (item.callback_query) {
  textoMensaje = item.callback_query.data ? String(item.callback_query.data).trim() : '';
  chatId = (item.callback_query.message && item.callback_query.message.chat) ? String(item.callback_query.message.chat.id) : '5016875501';
  fromName = (item.callback_query.from && (item.callback_query.from.first_name || item.callback_query.from.username)) || 'Usuario';
} else if (item.message) {
  textoMensaje = item.message.text ? String(item.message.text).trim() : '';
  chatId = (item.message.chat) ? String(item.message.chat.id) : '5016875501';
  fromName = (item.from && (item.from.first_name || item.from.username)) || 'Usuario';
} else {
  textoMensaje = item.text || '';
}

var mesObjetivoNombre = null;
var numeroSemanaObjetivo = null;
var mesNumeroObjetivo = null;
var semanaRelativa = null;
var anioObjetivo = hoy.getFullYear();
var nombreComando = 'Semana';
var esAnual = false;
var esReset = false;
var esAyuda = false;
var subMenuTipo = null;
var idEquipoReset = null;

var textoLower = textoMensaje.toLowerCase();

if (!modoForzado) {
  if (/^\/(ayuda|start|help|menu|menu_principal)(@|\s|$)/.test(textoLower)) {
    modo = 'ayuda';
    subMenuTipo = 'menu_principal';
  } else if (textoLower === '/menu_meses') {
    modo = 'ayuda';
    subMenuTipo = 'menu_meses';
  } else if (textoLower === '/menu_trimestres') {
    modo = 'ayuda';
    subMenuTipo = 'menu_trimestres';
  } else if (/^\/sem_q[1-4]$/.test(textoLower)) {
    modo = 'ayuda';
    subMenuTipo = textoLower.replace('/', '');
  } else if (textoLower === '/menu_reset') {
    modo = 'ayuda';
    subMenuTipo = 'menu_reset';
  } else if (/^\/reset_grp_v1[0-3]$/.test(textoLower)) {
    modo = 'ayuda';
    subMenuTipo = textoLower.replace('/', '');
  } else if (/^\/(reset|reiniciar)(@|\s|$)/.test(textoLower)) {
    modo = 'reset_equipo';
  } else if (/^\/anual(@|\s|$)/.test(textoLower)) {
    modo = 'informe_anual';
  } else if (/^\/mes(_?\d{1,2}|_actual)?(@|\s|$)/i.test(textoLower)) {
    modo = 'informe_mensual';
  } else if (textoLower.startsWith('/semana') || textoLower.startsWith('/reporte')) {
    modo = 'reporte_semana';
  }
}

if (modo === 'ayuda') {
  esAyuda = true;
} else if (modo === 'reset_equipo') {
  esReset = true;
  var mReset = textoMensaje.match(/\/(reset|reiniciar)(?:@\S+)?\s+(.+)/i);
  idEquipoReset = mReset ? mReset[2].trim().toUpperCase() : null;

} else if (modo === 'reporte_semana' || modo === 'reporte_diario_auto' || modo === 'alerta_2h') {
  var mSem = textoMensaje.match(/\/semana_?\s*(\d{1,2})/i);
  var numSemHoy = calcularNumeroSemana(hoy);

  if (mSem) {
    var valSem = parseInt(mSem[1], 10);
    if (valSem >= 1 && valSem <= 52) {
      numeroSemanaObjetivo = valSem;
      semanaRelativa = valSem;
      nombreComando = 'Semana' + valSem;
    }
  } else {
    numeroSemanaObjetivo = numSemHoy;
    var mesDeEstaSemana = mesMayoritarioDeSemana(numSemHoy);
    var semanasDeSuMes = semanasDelMes(mesDeEstaSemana.mes, mesDeEstaSemana.anio, numSemHoy);
    var idxSemHoy = semanasDeSuMes.indexOf(numSemHoy);
    semanaRelativa = idxSemHoy !== -1 ? (idxSemHoy + 1) : 1;
    nombreComando = 'Semana' + semanaRelativa;
  }

  var mesDeLaSemanaObjetivo = mesMayoritarioDeSemana(numeroSemanaObjetivo);
  mesNumeroObjetivo = mesDeLaSemanaObjetivo.mes + 1;
  mesObjetivoNombre = MESES_NOMBRE[mesDeLaSemanaObjetivo.mes];
  anioObjetivo = mesDeLaSemanaObjetivo.anio;

} else if (modo === 'informe_mensual') {
  var mMes = textoMensaje.match(/\/mes_?\s*(\d{1,2})/i);
  if (mMes) {
    mesNumeroObjetivo = parseInt(mMes[1], 10);
    if (mesNumeroObjetivo < 1) mesNumeroObjetivo = 1;
    if (mesNumeroObjetivo > 12) mesNumeroObjetivo = 12;
  } else {
    mesNumeroObjetivo = hoy.getMonth() + 1;
  }
  mesObjetivoNombre = MESES_NOMBRE[mesNumeroObjetivo - 1];
  nombreComando = 'Mes';

} else if (modo === 'informe_anual') {
  esAnual = true;
  nombreComando = 'Anual';
  mesNumeroObjetivo = hoy.getMonth() + 1;
  mesObjetivoNombre = MESES_NOMBRE[mesNumeroObjetivo - 1];
}

