// ======================================================
// ROYAL EXPRESS C.A. - CONTROL DE COMBUSTIBLE Y MANTENIMIENTO
// Funciones utilitarias compartidas
// ======================================================
var MESES_NOMBRE = ['ENERO','FEBRERO','MARZO','ABRIL','MAYO','JUNIO','JULIO','AGOSTO','SEPTIEMBRE','OCTUBRE','NOVIEMBRE','DICIEMBRE'];

function esc(s) {
  return String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function formatNum(val, dec) {
  var d = (dec === undefined) ? 1 : dec;
  var num = Number(val) || 0;
  var rounded = Math.round(num * Math.pow(10, d)) / Math.pow(10, d);
  var parts = rounded.toFixed(d).split('.');
  var integerPart = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return d > 0 ? integerPart + ',' + parts[1] : integerPart;
}

function pad2(n) { return (n < 10 ? '0' : '') + n; }

function formatFechaDDMMYY(fecha) {
  return pad2(fecha.getDate()) + '-' + pad2(fecha.getMonth() + 1) + '-' + String(fecha.getFullYear()).slice(-2);
}

function formatFechaLarga(fecha) {
  var dias = ['Domingo','Lunes','Martes','Miercoles','Jueves','Viernes','Sabado'];
  var mesCap = MESES_NOMBRE[fecha.getMonth()].charAt(0) + MESES_NOMBRE[fecha.getMonth()].slice(1).toLowerCase();
  return dias[fecha.getDay()] + ' ' + pad2(fecha.getDate()) + ' de ' + mesCap + ' de ' + fecha.getFullYear();
}

// Ancla oficial del calendario de semanas Royal Express: Semana 1 = Lunes 05-ene-2026
var ANCLA_SEMANA1 = new Date(2026, 0, 5);

function calcularNumeroSemana(fecha) {
  var diffMs = fecha.getTime() - ANCLA_SEMANA1.getTime();
  var diffDias = Math.floor(diffMs / 86400000);
  var numero = Math.floor(diffDias / 7) + 1;
  if (numero < 1) numero = 1;
  if (numero > 52) numero = 52;
  return numero;
}

function calcularRangoSemana(numeroSemana) {
  var inicio = new Date(ANCLA_SEMANA1.getTime() + (numeroSemana - 1) * 7 * 86400000);
  var fin = new Date(inicio.getTime() + 6 * 86400000);
  return { inicio: inicio, fin: fin };
}

function normalizarCodigo(codigo, placas) {
  if (codigo !== undefined && codigo !== null && String(codigo).trim() !== '') return String(codigo).trim().toUpperCase();
  if (placas !== undefined && placas !== null && String(placas).trim() !== '' && String(placas).trim() !== '---------') return String(placas).trim().toUpperCase();
  return 'N/D';
}

// ======================================================
// CLASIFICACION DE EQUIPOS SEGUN MANUAL DE MANTENIMIENTO ROYAL EXPRESS
// V10-xxx = Vehiculo Liviano (gasolina, 3km/L, mtto cada 7.000km)
// V13-xxx = Maquinaria Pesada (10L=1h, mtto cada 350h) - Retro/Montacarga/Soldar/Cargador/Grua
// Resto (V11/V12/otros en tabla gasoil) = Vehiculo Pesado (chutos y 750, gasoil, 1.5km/L, mtto cada 10.000km)
// ======================================================
var PALABRAS_MAQUINARIA = ['RETRO', 'MONTACARG', 'SOLDAR', 'CARGADOR', 'GRUA', 'GR\u00daA', 'EXCAVADORA'];

function clasificarEquipo(codigo, descripcion, esTablaGasolina) {
  var desc = String(descripcion || '').toUpperCase();
  var cod = String(codigo || '').toUpperCase();

  if (esTablaGasolina) {
    return { tipo: 'LIVIANO', rendimiento: 3, unidadRendimiento: 'km/L', limiteMtto: 7000, unidadMtto: 'km', combustible: 'GASOLINA' };
  }
  var esMaquinaria = cod.indexOf('V13-') === 0;
  if (!esMaquinaria) {
    for (var i = 0; i < PALABRAS_MAQUINARIA.length; i++) {
      if (desc.indexOf(PALABRAS_MAQUINARIA[i]) !== -1) { esMaquinaria = true; break; }
    }
  }
  if (esMaquinaria) {
    return { tipo: 'MAQUINARIA', rendimiento: 10, unidadRendimiento: 'L/hora', limiteMtto: 350, unidadMtto: 'horas', combustible: 'GASOIL' };
  }
  return { tipo: 'PESADO', rendimiento: 1.5, unidadRendimiento: 'km/L', limiteMtto: 10000, unidadMtto: 'km', combustible: 'GASOIL' };
}

function estimarKmUHoras(litrosConsumidos, clasificacion) {
  if (clasificacion.tipo === 'MAQUINARIA') return litrosConsumidos / 10;
  return litrosConsumidos * clasificacion.rendimiento;
}

function limiteDiario(clasificacion) {
  return clasificacion.combustible === 'GASOLINA' ? 30 : 80;
}

function numOr0(v) {
  var n = Number(v);
  return isNaN(n) ? 0 : n;
}

// ======================================================
// DETECCION DINAMICA DE ENCABEZADOS Y EXTRACCION DE TABLAS
// Trabaja sobre un arreglo de arreglos (values), tal como lo entrega
// la API de Microsoft Graph (workbook usedRange). Es tolerante a que
// las columnas cambien de orden y a que la cantidad de filas de
// equipos varie de un mes a otro.
// ======================================================
var ALIAS_COLUMNAS = {
  CANT: ['CANT'],
  DESCRIPCION: ['DESCRIPCION', 'DESCRIPCI\u00d3N'],
  CODIGO: ['CODIGO', 'C\u00d3DIGO'],
  PLACAS: ['PLACAS', 'PLACA'],
  COMB_DISP: ['COMB. DISP.', 'COMB DISP', 'COMBUSTIBLE DISPONIBLE'],
  SURT_PATIO: ['SURT. COMB. PATIO', 'SURT COMB PATIO', 'SURTIDO PATIO'],
  SURT_CLIENTE: ['SURT. COMB. CLIENTE', 'SURT COMB CLIENTE', 'SURTIDO CLIENTE'],
  COMB_INICIAL: ['COMB. INICIAL', 'COMBUSTIBLE INICIAL'],
  COMB_FINAL: ['COMB. FINAL', 'COMBUSTIBLE FINAL'],
  COMB_CONSUMIDO: ['COMB. CONSUMID (GASOIL)', 'COMB. CONSUMID (GASOLINA)', 'COMB. CONSUMIDO', 'COMBUSTIBLE CONSUMIDO'],
  SURTIDO_ES: ['SURTIDO DE COMB. E/S', 'SURTIDO E/S'],
  COMB_TOTAL: ['COMB. TOTAL', 'COMBUSTIBLE TOTAL'],
  DESTINO: ['DESTINO']
};

function limpiarCelda(v) {
  return (v === undefined || v === null) ? '' : String(v).trim().toUpperCase();
}

function esFilaEncabezado(fila) {
  var tieneCant = false, tieneDesc = false;
  for (var i = 0; i < fila.length; i++) {
    var c = limpiarCelda(fila[i]);
    if (c === 'CANT') tieneCant = true;
    if (c.indexOf('DESCRIPCION') === 0 || c.indexOf('DESCRIPCI\u00d3N') === 0) tieneDesc = true;
  }
  return tieneCant && tieneDesc;
}

function mapaColumnasDeFila(fila) {
  var mapa = {};
  for (var i = 0; i < fila.length; i++) {
    var c = limpiarCelda(fila[i]);
    if (!c) continue;
    Object.keys(ALIAS_COLUMNAS).forEach(function(campo) {
      if (mapa[campo] !== undefined) return;
      if (ALIAS_COLUMNAS[campo].indexOf(c) !== -1) mapa[campo] = i;
    });
  }
  return mapa;
}

function tipoCombustibleDeEncabezado(fila) {
  for (var i = 0; i < fila.length; i++) {
    var c = limpiarCelda(fila[i]);
    if (c.indexOf('GASOLINA') !== -1) return 'GASOLINA';
    if (c.indexOf('GASOIL') !== -1) return 'GASOIL';
  }
  return null;
}

function filaVacia(fila) {
  for (var i = 0; i < fila.length; i++) {
    if (limpiarCelda(fila[i]) !== '') return false;
  }
  return true;
}

function esFilaTotal(fila, mapa) {
  var idxRef = (mapa.PLACAS !== undefined) ? mapa.PLACAS : (mapa.DESCRIPCION !== undefined ? mapa.DESCRIPCION : 0);
  var val = limpiarCelda(fila[idxRef]);
  return val === 'TOTAL';
}

// Extrae todas las tablas (Gasoil / Gasolina) contenidas en la hoja diaria.
function extraerTablasDeHoja(values) {
  var tablas = [];
  var tipoTablaDefault = ['GASOIL', 'GASOLINA'];
  var contadorTablas = 0;
  var mapaAnterior = null;
  for (var r = 0; r < values.length; r++) {
    var fila = values[r];
    if (!esFilaEncabezado(fila)) continue;
    var mapa = mapaColumnasDeFila(fila);
    // Respaldo: si el encabezado de esta tabla no trae alguna columna
    // (por ejemplo CODIGO en la tabla de gasolina viene sin rotulo),
    // se reutiliza la posicion detectada en la tabla anterior de la
    // misma hoja, ya que ambas tablas comparten el mismo layout vertical.
    if (mapaAnterior) {
      Object.keys(mapaAnterior).forEach(function(campo) {
        if (mapa[campo] === undefined) mapa[campo] = mapaAnterior[campo];
      });
    }
    mapaAnterior = mapa;
    var tipoComb = tipoCombustibleDeEncabezado(fila) || tipoTablaDefault[contadorTablas] || 'GASOIL';
    contadorTablas++;
    var filasEquipo = [];
    for (var s = r + 1; s < values.length; s++) {
      var filaDatos = values[s];
      if (filaVacia(filaDatos)) break;
      if (esFilaTotal(filaDatos, mapa)) break;
      if (esFilaEncabezado(filaDatos)) break;
      var descripcion = mapa.DESCRIPCION !== undefined ? filaDatos[mapa.DESCRIPCION] : '';
      if (!descripcion && mapa.CANT !== undefined && (filaDatos[mapa.CANT] === undefined || filaDatos[mapa.CANT] === '')) continue;
      filasEquipo.push({
        cant: mapa.CANT !== undefined ? filaDatos[mapa.CANT] : null,
        descripcion: descripcion || '',
        codigo: mapa.CODIGO !== undefined ? filaDatos[mapa.CODIGO] : null,
        placas: mapa.PLACAS !== undefined ? filaDatos[mapa.PLACAS] : null,
        combDisp: numOr0(mapa.COMB_DISP !== undefined ? filaDatos[mapa.COMB_DISP] : 0),
        surtPatio: numOr0(mapa.SURT_PATIO !== undefined ? filaDatos[mapa.SURT_PATIO] : 0),
        surtCliente: numOr0(mapa.SURT_CLIENTE !== undefined ? filaDatos[mapa.SURT_CLIENTE] : 0),
        combInicial: numOr0(mapa.COMB_INICIAL !== undefined ? filaDatos[mapa.COMB_INICIAL] : 0),
        combFinal: numOr0(mapa.COMB_FINAL !== undefined ? filaDatos[mapa.COMB_FINAL] : 0),
        combConsumido: numOr0(mapa.COMB_CONSUMIDO !== undefined ? filaDatos[mapa.COMB_CONSUMIDO] : 0),
        surtidoES: numOr0(mapa.SURTIDO_ES !== undefined ? filaDatos[mapa.SURTIDO_ES] : 0),
        combTotal: numOr0(mapa.COMB_TOTAL !== undefined ? filaDatos[mapa.COMB_TOTAL] : 0),
        destino: mapa.DESTINO !== undefined ? filaDatos[mapa.DESTINO] : ''
      });
    }
    tablas.push({ tipoCombustible: tipoComb, filas: filasEquipo });
  }
  return tablas;
}

// ======================================================
// EXTRACCION DE LA HOJA SEMANAL "SEMANA #N" (RESUMEN LUNES..DOMINGO)
// ======================================================
var DIAS_SEMANA_HEADERS = ['LUNES', 'MARTES', 'MIERCOLES', 'MI\u00c9RCOLES', 'JUEVES', 'VIERNES', 'SABADO', 'S\u00c1BADO', 'DOMINGO'];

function esFilaEncabezadoSemanal(fila) {
  for (var i = 0; i < fila.length; i++) {
    if (limpiarCelda(fila[i]) === 'LUNES') return true;
  }
  return false;
}

function mapaColumnasSemanal(fila) {
  var mapa = { dias: {} };
  var nombresDias = ['LUNES', 'MARTES', 'MIERCOLES', 'JUEVES', 'VIERNES', 'SABADO', 'DOMINGO'];
  for (var i = 0; i < fila.length; i++) {
    var c = limpiarCelda(fila[i]).replace('\u00c9', 'E').replace('\u00c1', 'A');
    if (!c) continue;
    if (c === 'CANT') mapa.CANT = i;
    else if (c.indexOf('DESCRIPCION') === 0) mapa.DESCRIPCION = i;
    else if (c === 'CODIGO') mapa.CODIGO = i;
    else if (c.indexOf('PLACA') === 0) mapa.PLACAS = i;
    else if (nombresDias.indexOf(c) !== -1) mapa.dias[c] = i;
    else if (c.indexOf('TOTAL') !== -1) mapa.TOTAL = i;
  }
  return mapa;
}

function extraerTablaSemanal(values) {
  var resultado = { filas: [], resumenLineas: [], filaTotalIndex: -1 };
  var idxHeader = -1;
  for (var r = 0; r < values.length; r++) {
    if (esFilaEncabezadoSemanal(values[r])) { idxHeader = r; break; }
  }
  if (idxHeader === -1) return resultado;
  var mapa = mapaColumnasSemanal(values[idxHeader]);
  var nombresDias = ['LUNES', 'MARTES', 'MIERCOLES', 'JUEVES', 'VIERNES', 'SABADO', 'DOMINGO'];
  var r2 = idxHeader + 1;
  for (; r2 < values.length; r2++) {
    var fila = values[r2];
    if (filaVacia(fila)) break;
    var idxRef = mapa.PLACAS !== undefined ? mapa.PLACAS : (mapa.DESCRIPCION !== undefined ? mapa.DESCRIPCION : 0);
    if (limpiarCelda(fila[idxRef]) === 'TOTAL') { resultado.filaTotalIndex = r2; r2++; break; }
    var porDia = {};
    nombresDias.forEach(function(d) {
      porDia[d] = mapa.dias[d] !== undefined ? numOr0(fila[mapa.dias[d]]) : 0;
    });
    resultado.filas.push({
      descripcion: mapa.DESCRIPCION !== undefined ? fila[mapa.DESCRIPCION] : '',
      codigo: mapa.CODIGO !== undefined ? fila[mapa.CODIGO] : null,
      placas: mapa.PLACAS !== undefined ? fila[mapa.PLACAS] : null,
      porDia: porDia,
      total: mapa.TOTAL !== undefined ? numOr0(fila[mapa.TOTAL]) : 0
    });
  }
  for (; r2 < values.length; r2++) {
    var filaTxt = values[r2];
    if (filaVacia(filaTxt)) continue;
    var texto = filaTxt[1] !== undefined && filaTxt[1] !== null && String(filaTxt[1]).trim() !== '' ? filaTxt[1] : filaTxt.find(function(c) { return c !== undefined && c !== null && String(c).trim() !== ''; });
    if (texto) resultado.resumenLineas.push(String(texto).trim());
  }
  return resultado;
}

// ======================================================
// GUARDAR FECHA DE REINICIO DE MANTENIMIENTO PARA UN EQUIPO
// ======================================================
var d = $input.first().json;
var staticData = $getWorkflowStaticData('global');
if (!staticData.resetPorEquipo) staticData.resetPorEquipo = {};

if (!d.idEquipoReset) {
  return [{
    json: Object.assign({}, d, {
      message: '<b>ROYAL EXPRESS C.A.</b>\n\nUso correcto: <code>/reset CODIGO</code>\nEjemplo: <code>/reset V11-011</code>'
    })
  }];
}

var hoyISO = new Date().toISOString();
staticData.resetPorEquipo[d.idEquipoReset] = hoyISO;

return [{
  json: Object.assign({}, d, {
    message: '<b>ROYAL EXPRESS C.A. - MANTENIMIENTO</b>\n\nContador de mantenimiento reiniciado para el equipo <b>' + esc(d.idEquipoReset) + '</b>.\nFecha de reinicio: ' + formatFechaDDMMYY(new Date()) + '.\n\nA partir de ahora el acumulado de Km/Horas de este equipo se calculara desde esta fecha.'
  })
}];

// ======================================================
// FILTRAR CARPETA 'CONTROL MENSUAL COMBUSTIBLE 2026' DENTRO DEL LISTADO DE HIJOS
// ======================================================
var inputItems = $input.all();
var params = {};
try { params = $('Preparar Parametros de Ejecucion').first().json; } catch (e) {}

var listaHijos = [];
var primerJson = inputItems.length ? inputItems[0].json : {};
if (primerJson && Array.isArray(primerJson.value)) {
  listaHijos = primerJson.value;
} else {
  listaHijos = inputItems.map(function(it) { return it.json; }).filter(Boolean);
}

var carpeta = listaHijos.find(function(it) {
  return it && it.folder && it.name && it.name.trim().toUpperCase() === 'CONTROL MENSUAL COMBUSTIBLE 2026';
});

if (!carpeta) {
  var disponibles = listaHijos.map(function(it) { return it && it.name; }).filter(Boolean).join(', ') || 'ninguna';
  return [{
    json: Object.assign({}, params, {
      carpetaNoEncontrada: true,
      message: '<b>ROYAL EXPRESS C.A. - CONTROL DE COMBUSTIBLE</b>\n\nNo se encontro la carpeta \"CONTROL MENSUAL COMBUSTIBLE 2026\" dentro de la ruta esperada en OneDrive.\n\nCarpetas disponibles: ' + disponibles
    })
  }];
}

return [{ json: Object.assign({}, carpeta, params) }];

// ======================================================
// FILTRAR ARCHIVOS .XLSX DEL MES (RETORNA TODOS LOS ARCHIVOS HASTA EL MES CONSULTADO)
// ======================================================
var inputItems = $input.all();
var params = {};
try { params = $('Preparar Parametros de Ejecucion').first().json; } catch (e) {}

var listaArchivos = [];
var primerJson = inputItems.length ? inputItems[0].json : {};
if (primerJson && Array.isArray(primerJson.value)) {
  listaArchivos = primerJson.value;
} else {
  listaArchivos = inputItems.map(function(it) { return it.json; }).filter(Boolean);
}

var mesTargetNum = params.mesNumeroObjetivo || (new Date().getMonth() + 1);

if (!listaArchivos.length) {
  return [{
    json: Object.assign({}, params, {
      archivoNoEncontrado: true,
      message: '<b>ROYAL EXPRESS C.A. - CONTROL DE COMBUSTIBLE</b>\n\nLa carpeta "Control de Combustible 2026" no devolvió archivos. Verifica los permisos de OneDrive.'
    })
  }];
}

var archivosSeleccionados = [];

if (params.modo === 'informe_mensual' || params.modo === 'reporte_mes_actual' || params.modo === 'informe_anual' || params.modo === 'alerta_2h') {
  // NUEVO (RAMA DE ALERTAS): 'alerta_2h' se agrega a este grupo (en vez de
  // caer al 'else' de reporte semanal, que solo trae el archivo del mes
  // actual) para que "Evaluar Alertas de Mantenimiento" pueda calcular el
  // acumulado real de Km/Horas de cada equipo desde Enero (o desde su
  // ultimo /reset, sin importar en que mes ocurrio ese reset), igual que
  // ya lo hace el informe mensual/anual. No cambia el comportamiento de
  // ningun otro modo.
  // Retornar array con todos los archivos Excel desde Enero hasta el mes consultado (inclusive)
  archivosSeleccionados = listaArchivos.filter(function(a) {
    var nombre = (a && a.name) ? a.name.toUpperCase() : '';
    if (nombre.indexOf('.XLSX') === -1) return false;
    // CORREGIDO: los archivos reales se llaman "01_-CONTROL_COMBUSTIBLE_...xlsx"
    // (guion bajo + guion), no "01.-...". La regex anterior nunca hacía match,
    // así que ningún archivo pasaba el filtro y los informes mensual/anual
    // quedaban siempre en 0. Se acepta "_", "." o "-" (uno o varios) como
    // separador para tolerar variaciones futuras en el nombre.
    var mNum = nombre.match(/^(\d{2})[_.-]+/);
    if (mNum) {
      var numMesArch = parseInt(mNum[1], 10);
      // NUEVO: se incluye también el archivo del mes SIGUIENTE (si existe).
      // Cada Excel mensual le "presta" 1-2 días al archivo del mes siguiente para
      // cerrar su última semana (ej. el archivo de MARZO no tiene el 30 ni el 31,
      // esos dos días viven al inicio del archivo de ABRIL). Sin este +1, esos días
      // quedaban fuera del informe mensual/anual del mes objetivo. Es seguro incluirlo:
      // "Consolidar Filas de Hojas Leidas" y "Calcular Balance Mensual/Anual" ya
      // filtran cada registro por su FECHA REAL, así que los días de abril que
      // realmente son de abril se descartan solos y no se duplican ni se adelantan.
      return numMesArch <= Math.min(mesTargetNum + 1, 12);
    }
    return false;
  }).map(function(a) {
    var nombre = a.name.toUpperCase();
    var mNum = nombre.match(/^(\d{2})[_.-]+/);
    var numMesArch = mNum ? parseInt(mNum[1], 10) : mesTargetNum;
    return Object.assign({}, a, params, { mesNumeroArchivo: numMesArch });
  });
} else {
  // Para reporte semanal: traer solo el archivo del mes objetivo
  var mesBuscado = (params.mesObjetivoNombre || '').toUpperCase();
  var archivo = listaArchivos.find(function(a) {
    var nombre = (a && a.name) ? a.name.toUpperCase() : '';
    return nombre.indexOf('.XLSX') !== -1 && nombre.indexOf(mesBuscado) !== -1;
  });
  if (archivo) archivosSeleccionados.push(Object.assign({}, archivo, params));
}

if (!archivosSeleccionados.length) {
  var disponibles = listaArchivos.map(function(a) { return a && a.name; }).filter(Boolean).join(', ') || 'ninguno';
  return [{
    json: Object.assign({}, params, {
      archivoNoEncontrado: true,
      message: '<b>ROYAL EXPRESS C.A. - CONTROL DE COMBUSTIBLE</b>\n\nNo se encontraron archivos hasta el mes ' + mesTargetNum + ' en OneDrive.\nArchivos disponibles: ' + disponibles
    })
  }];
}

return archivosSeleccionados.map(function(arch) { return { json: arch }; });

// ======================================================
// ROYAL EXPRESS C.A. - DETERMINAR HOJAS A LEER
// (CORREGIDO: SOPORTA VARIOS ARCHIVOS/MESES EN UNA SOLA EJECUCIÓN)
// ======================================================
// Antes este nodo solo miraba el PRIMER item de entrada ($input.first()) y el
// PRIMER archivo devuelto por "Filtrar Archivo del Mes" ($('Filtrar Archivo del
// Mes').first()). Eso funcionaba para el reporte semanal (siempre llega 1 solo
// archivo) pero rompía el informe mensual, que desde "Filtrar Archivo del Mes"
// recibe VARIOS archivos (Enero..mes consultado) para poder acumular el año.
// Ahora se recorren TODOS los items de entrada (uno por cada archivo/mes) y se
// listan las hojas de cada uno, sin perder a qué archivo/mes pertenece cada hoja.
var ANCLA_SEMANA1 = new Date(2026, 0, 5); // Lunes 05-ene-2026

function calcularRangoSemana(numeroSemana) {
  var inicio = new Date(ANCLA_SEMANA1.getTime() + (numeroSemana - 1) * 7 * 86400000);
  var fin = new Date(inicio.getTime() + 6 * 86400000);
  return { inicio: inicio, fin: fin };
}

var esHojaDiaria = function(nombre) { return /^\d{2}-\d{2}-\d{2}$/.test(nombre); };
var esHojaSemana = function(nombre) { return /^SEMANA\s*#?\d+$/i.test(nombre); };

var itemsHojas = $input.all(); // 1 item por archivo -> { value: [ {name:..}, ... ] }

var paramsBase = {};
try { paramsBase = $('Preparar Parametros de Ejecucion').first().json; } catch (e) {}

var hojasObjetivo = [];

itemsHojas.forEach(function(item, idx) {
  // Recuperamos los datos del ARCHIVO (id, parentReference.driveId, mesNumeroArchivo, etc.)
  // que "Listar Hojas del Workbook" no conserva porque reemplaza el json con la
  // respuesta cruda de Graph API. Se recupera por posición (idx), igual patrón
  // que ya usa "Consolidar Filas de Hojas Leidas" más adelante en el flujo.
  var archivoOrigen = {};
  try { archivoOrigen = $('Archivo del Mes Encontrado').all()[idx].json; } catch (e) {}

  var paramsArchivo = Object.assign({}, paramsBase, archivoOrigen);
  var modo = paramsArchivo.modo;
  var hojas = (item.json && item.json.value) ? item.json.value : [];

  if (modo === 'reporte_semana') {
    var rango = calcularRangoSemana(paramsArchivo.numeroSemanaObjetivo);

    hojas.forEach(function(h) {
      var rawName = h.name || '';
      var cleanName = rawName.trim();

      if (esHojaDiaria(cleanName)) {
        var partes = cleanName.split('-');
        var fechaHoja = new Date(2000 + parseInt(partes[2], 10), parseInt(partes[1], 10) - 1, parseInt(partes[0], 10));
        if (fechaHoja >= rango.inicio && fechaHoja <= rango.fin) {
          hojasObjetivo.push({ json: Object.assign({}, paramsArchivo, { nombreHoja: cleanName, nombreHojaGraph: rawName, esHojaSemanal: false }) });
        }
      } else if (esHojaSemana(cleanName)) {
        var mSem = cleanName.match(/#?\s*(\d+)/);
        if (mSem) {
          var num = parseInt(mSem[1], 10);
          if (num <= paramsArchivo.numeroSemanaObjetivo) {
            hojasObjetivo.push({ json: Object.assign({}, paramsArchivo, { nombreHoja: cleanName, nombreHojaGraph: rawName, esHojaSemanal: true }) });
          }
        }
      }
    });
  } else {
    // Informe mensual (y cualquier otro modo que no sea semanal): se toman TODAS
    // las hojas diarias y semanales del archivo; el filtrado por mes objetivo vs.
    // acumulado del año se hace más adelante (Calcular Balance Mensual) usando la
    // fecha real de cada hoja / el mesNumeroArchivo de origen.
    hojas.forEach(function(h) {
      var rawName = h.name || '';
      var cleanName = rawName.trim();
      if (esHojaDiaria(cleanName) || esHojaSemana(cleanName)) {
        hojasObjetivo.push({ json: Object.assign({}, paramsArchivo, { nombreHoja: cleanName, nombreHojaGraph: rawName, esHojaSemanal: esHojaSemana(cleanName) }) });
      }
    });
  }
});

if (!hojasObjetivo.length) {
  return [{
    json: Object.assign({}, paramsBase, {
      hojasNoEncontradas: true,
      message: '<b>ROYAL EXPRESS C.A. - CONTROL DE COMBUSTIBLE</b>\n\nNo se encontraron hojas esperadas para ' + (paramsBase.mesObjetivoNombre || '') + '.'
    })
  }];
}

return hojasObjetivo;

// =====================================================
// ROYAL EXPRESS C.A. - CONSOLIDAR FILAS DE HOJAS LEÍDAS (MULTIMES CON SURTIDO E/S Y DESTINOS)
// =====================================================
var ALIAS_COLUMNAS = {
  CANT: ['CANT'],
  DESCRIPCION: ['DESCRIPCION', 'DESCRIPCIÓN'],
  CODIGO: ['CODIGO', 'CÓDIGO'],
  PLACAS: ['PLACAS', 'PLACA'],
  COMB_DISP: ['COMB. DISP.', 'COMB DISP', 'COMBUSTIBLE DISPONIBLE'],
  SURT_PATIO: ['SURT. COMB. PATIO', 'SURT COMB PATIO', 'SURTIDO PATIO'],
  SURT_CLIENTE: ['SURT. COMB. CLIENTE', 'SURT COMB CLIENTE', 'SURTIDO CLIENTE'],
  COMB_INICIAL: ['COMB. INICIAL', 'COMBUSTIBLE INICIAL'],
  COMB_FINAL: ['COMB. FINAL', 'COMBUSTIBLE FINAL'],
  COMB_CONSUMIDO: ['COMB. CONSUMID (GASOIL)', 'COMB. CONSUMID (GASOLINA)', 'COMB. CONSUMIDO', 'COMBUSTIBLE CONSUMIDO'],
  SURTIDO_ES: ['SURTIDO DE COMB. E/S', 'SURTIDO E/S', 'SURTIDO ES'],
  COMB_TOTAL: ['COMB. TOTAL', 'COMBUSTIBLE TOTAL'],
  DESTINO: ['DESTINO']
};

function limpiarCelda(v) {
  return (v === undefined || v === null) ? '' : String(v).trim().toUpperCase();
}

function esFilaEncabezado(fila) {
  var tieneCant = false, tieneDesc = false;
  for (var i = 0; i < fila.length; i++) {
    var c = limpiarCelda(fila[i]);
    if (c === 'CANT') tieneCant = true;
    if (c.indexOf('DESCRIPCION') === 0 || c.indexOf('DESCRIPCIÓN') === 0) tieneDesc = true;
  }
  return tieneCant && tieneDesc;
}

function mapaColumnasDeFila(fila) {
  var mapa = {};
  for (var i = 0; i < fila.length; i++) {
    var c = limpiarCelda(fila[i]);
    if (!c) continue;
    Object.keys(ALIAS_COLUMNAS).forEach(function(campo) {
      if (mapa[campo] !== undefined) return;
      if (ALIAS_COLUMNAS[campo].indexOf(c) !== -1) mapa[campo] = i;
    });
  }
  return mapa;
}

function tipoCombustibleDeEncabezado(fila) {
  for (var i = 0; i < fila.length; i++) {
    var c = limpiarCelda(fila[i]);
    if (c.indexOf('GASOLINA') !== -1) return 'GASOLINA';
    if (c.indexOf('GASOIL') !== -1) return 'GASOIL';
  }
  return null;
}

function filaVacia(fila) {
  for (var i = 0; i < fila.length; i++) {
    if (limpiarCelda(fila[i]) !== '') return false;
  }
  return true;
}

function esFilaTotal(fila, mapa) {
  var idxRef = (mapa.PLACAS !== undefined) ? mapa.PLACAS : (mapa.DESCRIPCION !== undefined ? mapa.DESCRIPCION : 0);
  var val = limpiarCelda(fila[idxRef]);
  return val === 'TOTAL';
}

function numOr0(v) {
  var n = Number(v);
  return isNaN(n) ? 0 : n;
}

// Campos cuya posición SÍ suele mantenerse estable entre la tabla de GASOIL y la
// de GASOLINA (identifican al equipo, no miden combustible), por eso es seguro
// heredarlos del encabezado anterior si no aparecen en el actual.
var CAMPOS_IDENTIDAD = ['CANT', 'DESCRIPCION', 'CODIGO', 'PLACAS'];
// Campos numéricos de combustible: CADA tabla debe traer su propia columna. NO se
// heredan de la tabla anterior (ver nota más abajo).
var CAMPOS_COMBUSTIBLE = ['COMB_DISP', 'SURT_PATIO', 'SURT_CLIENTE', 'COMB_INICIAL', 'COMB_FINAL', 'COMB_CONSUMIDO', 'SURTIDO_ES', 'COMB_TOTAL'];
var ETIQUETA_CAMPO = {
  COMB_DISP: 'COMB. DISP.', SURT_PATIO: 'SURT. COMB. PATIO', SURT_CLIENTE: 'SURT. COMB. CLIENTE',
  COMB_INICIAL: 'COMB. INICIAL', COMB_FINAL: 'COMB. FINAL', COMB_CONSUMIDO: 'COMB. CONSUMIDO',
  SURTIDO_ES: 'SURTIDO DE COMB. E/S', COMB_TOTAL: 'COMB. TOTAL'
};

function extraerTablasDeHoja(values) {
  var tablas = [];
  var tipoTablaDefault = ['GASOIL', 'GASOLINA'];
  var contadorTablas = 0;
  var mapaAnterior = null;
  for (var r = 0; r < values.length; r++) {
    var fila = values[r];
    if (!esFilaEncabezado(fila)) continue;
    var mapa = mapaColumnasDeFila(fila);
    // CORREGIDO: antes se heredaban TODOS los campos que faltaran en el
    // encabezado actual desde el encabezado de la tabla anterior (de GASOIL a
    // GASOLINA). Eso es correcto para los campos de identidad (posición estable),
    // pero era peligroso para los campos numéricos: si un día el encabezado de
    // GASOLINA no traía columna propia de "SURT. COMB. PATIO" (por ejemplo quedó
    // fusionada/renombrada como "SURTIDO DE COMB. E/S"), el código heredaba el
    // índice de esa columna desde GASOIL y terminaba leyendo el MISMO valor como
    // "surt. patio" y como "surtido E/S" a la vez, inflando el KPI "Comb. Inicial
    // Semana". Ahora los campos de combustible se leen ÚNICAMENTE del encabezado
    // de su propia tabla; si no aparecen ahí, quedan en 0 (no se inventan) y se
    // registra la columna faltante en `camposFaltantes` para poder alertar.
    var camposFaltantes = [];
    if (mapaAnterior) {
      Object.keys(mapaAnterior).forEach(function(campo) {
        if (mapa[campo] === undefined && CAMPOS_IDENTIDAD.indexOf(campo) !== -1) {
          mapa[campo] = mapaAnterior[campo];
        }
      });
    }
    CAMPOS_COMBUSTIBLE.forEach(function(campo) {
      if (mapa[campo] === undefined) camposFaltantes.push(ETIQUETA_CAMPO[campo] || campo);
    });
    mapaAnterior = mapa;
    var tipoComb = tipoCombustibleDeEncabezado(fila) || tipoTablaDefault[contadorTablas] || 'GASOIL';
    contadorTablas++;
    var filasEquipo = [];
    for (var s = r + 1; s < values.length; s++) {
      var filaDatos = values[s];
      if (filaVacia(filaDatos)) break;
      if (esFilaTotal(filaDatos, mapa)) break;
      if (esFilaEncabezado(filaDatos)) break;
      var descripcion = mapa.DESCRIPCION !== undefined ? filaDatos[mapa.DESCRIPCION] : '';
      if (!descripcion && mapa.CANT !== undefined && (filaDatos[mapa.CANT] === undefined || filaDatos[mapa.CANT] === '')) continue;

      var codigo = mapa.CODIGO !== undefined ? filaDatos[mapa.CODIGO] : null;
      var placas = mapa.PLACAS !== undefined ? filaDatos[mapa.PLACAS] : null;

      filasEquipo.push({
        cant: mapa.CANT !== undefined ? filaDatos[mapa.CANT] : null,
        descripcion: descripcion || '',
        codigo: codigo || null,
        placas: placas || null,
        combDisp: numOr0(mapa.COMB_DISP !== undefined ? filaDatos[mapa.COMB_DISP] : 0),
        surtPatio: numOr0(mapa.SURT_PATIO !== undefined ? filaDatos[mapa.SURT_PATIO] : 0),
        surtCliente: numOr0(mapa.SURT_CLIENTE !== undefined ? filaDatos[mapa.SURT_CLIENTE] : 0),
        combInicial: numOr0(mapa.COMB_INICIAL !== undefined ? filaDatos[mapa.COMB_INICIAL] : 0),
        combFinal: numOr0(mapa.COMB_FINAL !== undefined ? filaDatos[mapa.COMB_FINAL] : 0),
        combConsumido: numOr0(mapa.COMB_CONSUMIDO !== undefined ? filaDatos[mapa.COMB_CONSUMIDO] : 0),
        surtidoES: numOr0(mapa.SURTIDO_ES !== undefined ? filaDatos[mapa.SURTIDO_ES] : 0),
        combTotal: numOr0(mapa.COMB_TOTAL !== undefined ? filaDatos[mapa.COMB_TOTAL] : 0),
        destino: mapa.DESTINO !== undefined ? filaDatos[mapa.DESTINO] : ''
      });
    }
    tablas.push({ tipoCombustible: tipoComb, filas: filasEquipo, camposFaltantes: camposFaltantes });
  }
  return tablas;
}

function esFilaEncabezadoSemanal(fila) {
  for (var i = 0; i < fila.length; i++) {
    if (limpiarCelda(fila[i]) === 'LUNES') return true;
  }
  return false;
}

function mapaColumnasSemanal(fila) {
  var mapa = { dias: {} };
  var nombresDias = ['LUNES', 'MARTES', 'MIERCOLES', 'JUEVES', 'VIERNES', 'SABADO', 'DOMINGO'];
  for (var i = 0; i < fila.length; i++) {
    var c = limpiarCelda(fila[i]).replace('É', 'E').replace('Á', 'A');
    if (!c) continue;
    if (c === 'CANT') mapa.CANT = i;
    else if (c.indexOf('DESCRIPCION') === 0) mapa.DESCRIPCION = i;
    else if (c === 'CODIGO') mapa.CODIGO = i;
    else if (c.indexOf('PLACA') === 0) mapa.PLACAS = i;
    else if (nombresDias.indexOf(c) !== -1) mapa.dias[c] = i;
    else if (c.indexOf('TOTAL') !== -1) mapa.TOTAL = i;
  }
  return mapa;
}

function extraerTablaSemanal(values) {
  var resultado = { filas: [], resumenLineas: [], filaTotalIndex: -1 };
  var idxHeader = -1;
  for (var r = 0; r < values.length; r++) {
    if (esFilaEncabezadoSemanal(values[r])) { idxHeader = r; break; }
  }
  if (idxHeader === -1) return resultado;
  var mapa = mapaColumnasSemanal(values[idxHeader]);
  var nombresDias = ['LUNES', 'MARTES', 'MIERCOLES', 'JUEVES', 'VIERNES', 'SABADO', 'DOMINGO'];
  var r2 = idxHeader + 1;
  for (; r2 < values.length; r2++) {
    var fila = values[r2];
    if (filaVacia(fila)) break;
    var idxRef = mapa.PLACAS !== undefined ? mapa.PLACAS : (mapa.DESCRIPCION !== undefined ? mapa.DESCRIPCION : 0);
    if (limpiarCelda(fila[idxRef]) === 'TOTAL') { resultado.filaTotalIndex = r2; r2++; break; }
    var porDia = {};
    nombresDias.forEach(function(d) {
      porDia[d] = mapa.dias[d] !== undefined ? numOr0(fila[mapa.dias[d]]) : 0;
    });
    resultado.filas.push({
      descripcion: mapa.DESCRIPCION !== undefined ? fila[mapa.DESCRIPCION] : '',
      codigo: mapa.CODIGO !== undefined ? fila[mapa.CODIGO] : null,
      placas: mapa.PLACAS !== undefined ? fila[mapa.PLACAS] : null,
      porDia: porDia,
      total: mapa.TOTAL !== undefined ? numOr0(fila[mapa.TOTAL]) : 0
    });
  }
  for (; r2 < values.length; r2++) {
    var filaTxt = values[r2];
    if (filaVacia(filaTxt)) continue;
    var texto = filaTxt[1] !== undefined && filaTxt[1] !== null && String(filaTxt[1]).trim() !== '' ? filaTxt[1] : filaTxt.find(function(c) { return c !== undefined && c !== null && String(c).trim() !== ''; });
    if (texto) resultado.resumenLineas.push(String(texto).trim());
  }
  return resultado;
}

var items = $input.all();
var params = {};
try { params = $('Determinar Hojas a Leer').first().json; } catch (e) {}

var diasProcesados = [];
var semanasProcesadas = [];

items.forEach(function(item, idx) {
  var origen = {};
  try { origen = $('Determinar Hojas a Leer').all()[idx].json; } catch (e) {}
  var values = (item.json && item.json.values) ? item.json.values : [];
  if (!values.length) return;

  if (origen.esHojaSemanal) {
    // CORREGIDO: la expresión regular había quedado con barras invertidas de más
    // (\\s y \\d en vez de \s y \d), lo que hacía que NUNCA reconociera el número
    // de semana en nombres de hoja como "SEMANA #3" (mSem siempre salía null).
    // Eso rompía el reporte semanal completo y el desglose por semana del mensual/anual.
    var mSem = (origen.nombreHoja || '').match(/#?\s*(\d+)/);
    var numeroSemana = mSem ? parseInt(mSem[1], 10) : null;
    var extraidoSemanal = extraerTablaSemanal(values);
    semanasProcesadas.push({
      numeroSemana: numeroSemana,
      nombreHoja: origen.nombreHoja,
      mesNumeroArchivo: origen.mesNumeroArchivo || null,
      filas: extraidoSemanal.filas,
      resumenLineas: extraidoSemanal.resumenLineas
    });
  } else {
    var partes = (origen.nombreHoja || '').split('-');
    var fecha = partes.length === 3 ? new Date(2000 + parseInt(partes[2], 10), parseInt(partes[1], 10) - 1, parseInt(partes[0], 10)) : null;
    var tablas = extraerTablasDeHoja(values);
    diasProcesados.push({
      nombreHoja: origen.nombreHoja,
      fecha: fecha,
      fechaISO: fecha ? fecha.toISOString() : null,
      mesNumeroArchivo: origen.mesNumeroArchivo || null,
      tablas: tablas
    });
  }
});

diasProcesados.sort(function(a, b) { return (a.fecha ? a.fecha.getTime() : 0) - (b.fecha ? b.fecha.getTime() : 0); });
semanasProcesadas.sort(function(a, b) { return (a.numeroSemana || 0) - (b.numeroSemana || 0); });

var historialConsumosGasoil = [];
var historialConsumosGasolina = [];

// Consolidación global: se asegura de registrar tanto consumo como surtido en E/S
diasProcesados.forEach(function(dia) {
  (dia.tablas || []).forEach(function(tabla) {
    var destino = tabla.tipoCombustible === 'GASOLINA' ? historialConsumosGasolina : historialConsumosGasoil;
    (tabla.filas || []).forEach(function(fila) {
      if (!fila.combConsumido && !fila.surtidoES) return;
      destino.push({
        codigo: fila.codigo,
        descripcion: fila.descripcion,
        placas: fila.placas,
        destinoViaje: fila.destino,
        combConsumido: fila.combConsumido || 0,
        surtidoES: fila.surtidoES || 0,
        fecha: dia.fechaISO,
        nombreHoja: dia.nombreHoja,
        mesNumeroArchivo: dia.mesNumeroArchivo || null
      });
    });
  });
});

// ======================================================
// ALERTAS DE CALIDAD DE DATOS (NUEVO)
// ======================================================
// Objetivo: avisar en el reporte cuando algo en la captura diaria "se ve raro",
// para que la persona que llena los Excel sepa exactamente qué día y qué revisar.
// No corrige ningún número automáticamente, solo informa.
var alertasCalidadDatos = [];

// 1) Encabezado incompleto: a la tabla de ese día le faltó alguna columna de
//    combustible en su propio encabezado (ver extraerTablasDeHoja más arriba).
diasProcesados.forEach(function(dia) {
  (dia.tablas || []).forEach(function(tabla) {
    if (tabla.camposFaltantes && tabla.camposFaltantes.length) {
      alertasCalidadDatos.push({
        tipo: 'ENCABEZADO_INCOMPLETO',
        fecha: dia.nombreHoja,
        tipoCombustible: tabla.tipoCombustible,
        detalle: 'Faltan columnas en el encabezado: ' + tabla.camposFaltantes.join(', ')
      });
    }
  });
});

// 2) Código inusual: un día trae un código de equipo que no aparece en la
//    mayoría de los demás días de ESE MISMO MES (agrupado por mesNumeroArchivo,
//    no por todo el rango cargado) para la misma tabla (gasoil/gasolina) —
//    típico síntoma de un typo al capturar el código (ej. escribir V13-012 en el
//    renglón que ese mes siempre es V13-006). Se agrupa por mes y no de forma
//    global porque el informe mensual/anual puede cargar varios meses a la vez
//    (para resolver semanas que cruzan de un mes a otro) y un recodificado real
//    de equipo (ej. V13-003 -> V13-004 a partir de cierta fecha) no debe
//    "contaminar" el patrón de los meses anteriores. Umbral: se necesitan al
//    menos 3 días en ese mes para sacar un patrón confiable.
(function detectarCodigosInusuales() {
  var porGrupo = {}; // key = tipoCombustible + '|' + mesNumeroArchivo
  diasProcesados.forEach(function(dia) {
    (dia.tablas || []).forEach(function(tabla) {
      var key = tabla.tipoCombustible + '|' + (dia.mesNumeroArchivo || '0');
      if (!porGrupo[key]) porGrupo[key] = { tipo: tabla.tipoCombustible, entradas: [] };
      var codigosDelDia = {};
      (tabla.filas || []).forEach(function(f) {
        if (f.codigo) codigosDelDia[String(f.codigo).toUpperCase().trim()] = true;
      });
      porGrupo[key].entradas.push({ nombreHoja: dia.nombreHoja, codigos: codigosDelDia });
    });
  });

  Object.keys(porGrupo).forEach(function(key) {
    var grupo = porGrupo[key];
    var entradas = grupo.entradas;
    if (entradas.length < 3) return;

    var frecuencia = {};
    entradas.forEach(function(e) {
      Object.keys(e.codigos).forEach(function(c) { frecuencia[c] = (frecuencia[c] || 0) + 1; });
    });
    var totalDias = entradas.length;
    var habituales = Object.keys(frecuencia).filter(function(c) { return frecuencia[c] > totalDias / 2; });

    entradas.forEach(function(e) {
      var faltantes = habituales.filter(function(c) { return !e.codigos[c]; });
      var inesperados = Object.keys(e.codigos).filter(function(c) { return frecuencia[c] <= totalDias / 2; });
      if (faltantes.length || inesperados.length) {
        var detalle = [];
        if (inesperados.length) detalle.push('apareció código no habitual: ' + inesperados.join(', '));
        if (faltantes.length) detalle.push('no aparece el código habitual: ' + faltantes.join(', '));
        alertasCalidadDatos.push({
          tipo: 'CODIGO_INUSUAL',
          fecha: e.nombreHoja,
          tipoCombustible: grupo.tipo,
          detalle: detalle.join(' / ')
        });
      }
    });
  });
})();

return [{
  json: Object.assign({}, params, {
    diasProcesados: diasProcesados,
    semanasProcesadas: semanasProcesadas,
    historialConsumosGasoil: historialConsumosGasoil,
    historialConsumosGasolina: historialConsumosGasolina,
    alertasCalidadDatos: alertasCalidadDatos
  })
}];

// ======================================================
// ROYAL EXPRESS C.A. - CALCULAR BALANCE SEMANAL (META 1.000 L/SEM)
// ======================================================
var inputItems = $input.all();
var d = inputItems.length ? inputItems[0].json : {};

var hoy = new Date();
var ANCLA_SEMANA1 = new Date(2026, 0, 5); // Lunes 05-ene-2026

function calcularNumeroSemana(fecha) {
  var diffMs = fecha.getTime() - ANCLA_SEMANA1.getTime();
  var diffDias = Math.floor(diffMs / 86400000);
  var numero = Math.floor(diffDias / 7) + 1;
  // CORREGIDO: ver nota en "Preparar Parametros de Ejecucion" — no se debe forzar
  // a semana 1 lo que en realidad es la Semana #0 (pre-temporada).
  if (numero < 0) numero = 0;
  if (numero > 52) numero = 52;
  return numero;
}

function calcularRangoSemana(numeroSemana) {
  var inicio = new Date(ANCLA_SEMANA1.getTime() + (numeroSemana - 1) * 7 * 86400000);
  var fin = new Date(inicio.getTime() + 6 * 86400000);
  return { inicio: inicio, fin: fin };
}

function pad2(n) { return (n < 10 ? '0' : '') + n; }

function formatFechaDDMMYY(fecha) {
  return pad2(fecha.getDate()) + '/' + pad2(fecha.getMonth() + 1) + '/' + fecha.getFullYear();
}

function formatRangoFechasTexto(inicio, fin) {
  var MESES = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
  if (inicio.getMonth() === fin.getMonth()) {
    return 'Del ' + pad2(inicio.getDate()) + ' al ' + pad2(fin.getDate()) + ' de ' + MESES[inicio.getMonth()] + ' ' + inicio.getFullYear();
  } else {
    return 'Del ' + pad2(inicio.getDate()) + ' de ' + MESES[inicio.getMonth()] + ' al ' + pad2(fin.getDate()) + ' de ' + MESES[fin.getMonth()] + ' ' + inicio.getFullYear();
  }
}

var numeroSemanaActual = d.numeroSemanaObjetivo || calcularNumeroSemana(hoy);
var rangoSemanaActual = calcularRangoSemana(numeroSemanaActual);
var rangoTexto = formatRangoFechasTexto(rangoSemanaActual.inicio, rangoSemanaActual.fin);

var ASIGNACION_SEMANAL = 1000; // Meta semanal 1.000 L
var ASIGNACION_MENSUAL = 4000; // Meta mensual 4.000 L

var catalogoReal = {};
try {
  var catData = $('Parsear Catalogo Equipos (DATA)').first().json;
  catalogoReal = (catData && catData.catalogoEquipos) ? catData.catalogoEquipos : {};
} catch(e) {}

function normalizarPlaca(p) {
  return String(p || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
}

function obtenerInfoEquipo(codigo, placaFila, descFila) {
  var cod = String(codigo || '').toUpperCase().trim();
  var placa = placaFila && String(placaFila).trim() !== '---------' ? String(placaFila).trim() : '';
  var desc = descFila || '';

  if (cod && catalogoReal[cod]) {
    if (!placa || placa === '---------') placa = catalogoReal[cod].placa || '';
    if (!desc) desc = catalogoReal[cod].descripcion || '';
  } else if (!cod && placa) {
    var pNorm = normalizarPlaca(placa);
    var matchCod = Object.keys(catalogoReal).find(function(k) {
      return normalizarPlaca(catalogoReal[k].placa) === pNorm;
    });
    if (matchCod) {
      cod = matchCod;
      if (!desc) desc = catalogoReal[cod].descripcion || '';
    }
  }
  return { codigo: cod || 'N/D', placa: placa || 'N/A', descripcion: desc || 'Sin descripción' };
}

// CORREGIDO: antes, el consumo de la semana (consumoSemanalActual, listaEquipos,
// consumoPorDiaSemana) se leia de la hoja "SEMANA #N" escrita a mano. Esa hoja
// puede quedar desactualizada mientras la semana está en curso (el personal
// carga primero las hojas diarias y compila la hoja resumen despues), y ademas
// queda mal etiquetada en semanas que cruzan de un mes a otro. Ahora todo se
// suma directo de las hojas DIARIAS (igual que el KPI mensual), que siempre
// están al día y correctamente fechadas.
var combInicialSemanaTotal = 0;
var destinosPorEquipo = {};
var registrosSurtidoES = [];
var primerDiaProcesado = false;
var consumoPorEquipoSemana = {};
var consumoPorDiaSemana = [0, 0, 0, 0, 0, 0, 0];

(d.diasProcesados || []).forEach(function(dia) {
  var fechaObj = dia.fecha ? new Date(dia.fecha) : null;
  if (!fechaObj) return;

  var numSemRow = calcularNumeroSemana(fechaObj);
  if (numSemRow !== numeroSemanaActual) return;

  var esPrimerDia = !primerDiaProcesado;
  primerDiaProcesado = true;

  var idxDia = Math.round((fechaObj.getTime() - rangoSemanaActual.inicio.getTime()) / 86400000);

  (dia.tablas || []).forEach(function(tabla) {
    (tabla.filas || []).forEach(function(f) {
      var info = obtenerInfoEquipo(f.codigo, f.placas, f.descripcion);
      var key = info.codigo !== 'N/D' ? info.codigo : (info.descripcion + '_' + info.placa);

      if (esPrimerDia) {
        var quedaba = Number(f.combInicial) || 0;
        var surtPatio = Number(f.surtPatio) || 0;
        combInicialSemanaTotal += (quedaba + surtPatio);
      }

      if (f.destino && f.destino !== '---------' && f.destino.trim() !== '') {
        if (!destinosPorEquipo[key]) destinosPorEquipo[key] = [];
        if (destinosPorEquipo[key].indexOf(f.destino.trim()) === -1) {
          destinosPorEquipo[key].push(f.destino.trim());
        }
      }

      if (Number(f.surtidoES) > 0) {
        registrosSurtidoES.push({
          fecha: formatFechaDDMMYY(fechaObj),
          codigo: info.codigo,
          placa: info.placa,
          cantidad: Number(f.surtidoES),
          estacion: 'E/S EXTERNA',
          destino: f.destino || 'BASE RX',
          obs: 'Surtido Autorizado'
        });
      }

      // Solo GASOIL: la meta semanal/mensual y la hoja "SEMANA #N" original
      // siempre fueron solo de gasoil, se mantiene el mismo criterio.
      if (tabla.tipoCombustible === 'GASOIL') {
        var consumido = Number(f.combConsumido) || 0;
        if (idxDia >= 0 && idxDia <= 6) {
          consumoPorDiaSemana[idxDia] += consumido;
        }
        if (consumido > 0) {
          if (!consumoPorEquipoSemana[key]) {
            consumoPorEquipoSemana[key] = { codigo: info.codigo, descripcion: info.descripcion, placa: info.placa, total: 0 };
          }
          consumoPorEquipoSemana[key].total += consumido;
        }
      }
    });
  });
});

var surtidoESTotal = registrosSurtidoES.reduce(function(acc, r) { return acc + r.cantidad; }, 0);

var etiquetasDiasSemana = ['Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb', 'Dom'];
for (var i = 0; i < 7; i++) {
  var diaF = new Date(rangoSemanaActual.inicio.getTime() + i * 86400000);
  var nombresCortos = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];
  etiquetasDiasSemana[i] = nombresCortos[diaF.getDay()] + ' ' + pad2(diaF.getDate());
}

var listaEquipos = Object.keys(consumoPorEquipoSemana).map(function(key) {
  var e = consumoPorEquipoSemana[key];
  var dests = destinosPorEquipo[key] || [];
  return {
    codigo: e.codigo,
    descripcion: e.descripcion,
    placas: e.placa,
    placa: e.placa,
    combustible: 'GASOIL',
    consumoSemana: Math.round(e.total * 10) / 10,
    destino: dests.length ? dests.join(' / ') : 'BASE RX'
  };
}).sort(function(a, b) { return b.consumoSemana - a.consumoSemana; });

var consumoSemanalActual = listaEquipos.reduce(function(acc, e) { return acc + e.consumoSemana; }, 0);

// Semanas YA CERRADAS (anteriores a la actual): la hoja "SEMANA #N" de esas ya
// fue conciliada por el personal, así que se sigue usando como fuente (evita
// tener que releer todas las hojas diarias del mes completo). La semana ACTUAL
// se suma con el total recién calculado arriba (fresco, desde hojas diarias).
var consumidoAcumuladoMes = 0;
(d.semanasProcesadas || []).forEach(function(s) {
  if (s.numeroSemana < numeroSemanaActual && s.filas) {
    s.filas.forEach(function(f) {
      consumidoAcumuladoMes += Number(f.total) || 0;
    });
  }
});
consumidoAcumuladoMes += consumoSemanalActual;

// NUEVO: acota las alertas de calidad de datos (ver "Consolidar Filas de Hojas
// Leídas") solo a los días DENTRO de la semana de este reporte. Si en algún
// momento este nodo llega a recibir datos de más días (ej. un cambio futuro que
// cargue más de una semana), evita que el reporte semanal muestre avisos de
// otras fechas que no tienen nada que ver con esta semana.
function parsearFechaDDMMYY(nombreHoja) {
  var partes = String(nombreHoja || '').split('-');
  if (partes.length !== 3) return null;
  return new Date(2000 + parseInt(partes[2], 10), parseInt(partes[1], 10) - 1, parseInt(partes[0], 10));
}
var alertasCalidadDatosSemana = (d.alertasCalidadDatos || []).filter(function(a) {
  var f = parsearFechaDDMMYY(a.fecha);
  return f && f >= rangoSemanaActual.inicio && f <= rangoSemanaActual.fin;
});

return [{
  json: Object.assign({}, d, {
    modo: 'reporte_semana',
    tipoReporte: 'SEMANAL',
    numeroSemanaActual: numeroSemanaActual,
    rangoTexto: rangoTexto,
    combInicialSemana: Math.round(combInicialSemanaTotal * 10) / 10,
    surtidoESTotal: Math.round(surtidoESTotal * 10) / 10,
    consumoSemanalActual: Math.round(consumoSemanalActual * 10) / 10,
    asignacionSemanal: ASIGNACION_SEMANAL,
    asignacionMensual: ASIGNACION_MENSUAL,
    consumidoAcumuladoMes: Math.round(consumidoAcumuladoMes * 10) / 10,
    equiposSemanal: listaEquipos,
    registrosSurtidoES: registrosSurtidoES,
    consumoPorDiaSemana: consumoPorDiaSemana.map(function(v) { return Math.round(v * 10) / 10; }),
    etiquetasDiasSemana: etiquetasDiasSemana,
    alertasCalidadDatos: alertasCalidadDatosSemana
  })
}];

// =====================================================
// ROYAL EXPRESS C.A. - CALCULAR BALANCE MENSUAL (CON SURTIDO E/S Y GRUPOS OFICIALES)
