// CORREGIDO: antes se armaba desde las hojas "SEMANA #N" escritas a mano,
// filtrando por el ARCHIVO de origen de esa hoja (mesNumeroArchivo). Eso excluía
// las semanas que cruzan de un mes a otro (la hoja vive en el archivo del mes
// vecino aunque parte de sus días sí sean del mes consultado), y por eso el
// total de "semanasBreakdown" quedaba por debajo del KPI principal del mes.
// Ahora se arma directo del mapa gasoilPorSemanaMap, que ya viene agrupado por
// la FECHA REAL de cada registro diario (igual criterio que consumidoGasoilMes),
// así los dos números siempre cuadran entre sí.
var numerosSemanaDelMes = Object.keys(gasoilPorSemanaMap).map(Number);
Object.keys(surtidoESPorSemanaMap).forEach(function(n) {
  if (numerosSemanaDelMes.indexOf(Number(n)) === -1) numerosSemanaDelMes.push(Number(n));
});
numerosSemanaDelMes.sort(function(a, b) { return a - b; });

var semanasBreakdown = numerosSemanaDelMes.map(function(numSem) {
  var totSem = gasoilPorSemanaMap[numSem] || 0;
  var surtES = surtidoESPorSemanaMap[numSem] || 0;
  return {
    numeroSemana: numSem,
    label: 'Semana #' + numSem,
    totalGasoil: Math.round(totSem * 10) / 10,
    surtidoES: Math.round(surtES * 10) / 10
  };
});

// NUEVO: acota las alertas de calidad de datos solo a los días del MES
// objetivo. El nodo puede recibir hojas de meses vecinos (para resolver
// semanas que cruzan de un mes a otro), pero el informe mensual de, por
// ejemplo, agosto no debería mostrar avisos acumulados desde enero.
function parsearFechaDDMMYYMensual(nombreHoja) {
  var partes = String(nombreHoja || '').split('-');
  if (partes.length !== 3) return null;
  return { mes: parseInt(partes[1], 10) };
