    asignacionSemanal: ASIGNACION_SEMANAL,
    consumidoGasoilMes: Math.round(consumidoGasoilMes * 10) / 10,
    consumidoGasolinaMes: Math.round(consumidoGasolinaMes * 10) / 10,
    surtidoESTotalMes: Math.round(surtidoESTotalMes * 10) / 10,
    equiposMensual: listaEquiposMensual,
    top10EquiposMes: top10EquiposMes,
    top10EquiposAnual: top10EquiposAnual,
    semanasBreakdown: semanasBreakdown,
    alertasCalidadDatos: alertasCalidadDatosMes
  })
}];

// ======================================================
// PARSEAR HOJA "DATA" (CODIFICACIONES DE EQUIPOS Y/O MAQUINARIAS)
// Convierte el rango crudo de la hoja DATA del archivo del mes en un
// catalogo {codigo: {descripcion, placa}}. Este catalogo REAL reemplaza
// al catalogo fijo que antes estaba escrito a mano dentro del codigo
// (y que ya no coincidia con la flota real: le faltaban los 25 equipos
// V12-xxx y tenia varias placas corridas de codigo).
// ======================================================
var resp = $input.first().json;
var values = (resp && resp.values) ? resp.values : [];

function limpiar(v) {
  return (v === undefined || v === null) ? '' : String(v).trim();
}

var catalogo = {};
for (var r = 0; r < values.length; r++) {
  var fila = values[r] || [];
  var codigo = limpiar(fila[1]).toUpperCase();   // columna B = CODIGO
  var descripcion = limpiar(fila[2]);            // columna C = TIPO/DESCRIPCION
  var placa = limpiar(fila[3]);                  // columna D = PLACAS/SERIAL
  if (!/^V\d{2}-\d{3}$/.test(codigo)) continue; // saltar encabezados y filas vacias
  catalogo[codigo] = { descripcion: descripcion, placa: placa };
}

return [{ json: { catalogoEquipos: catalogo, totalEquiposCatalogo: Object.keys(catalogo).length } }];

// =====================================================
// ROYAL EXPRESS C.A. - CALCULAR BALANCE ANUAL (48.000 L / AÑO - GRUPOS V10-V13)
// =====================================================
var inputItems = $input.all();
var d = inputItems.length ? inputItems[0].json : {};

var MESES_NOMBRE = ['ENERO','FEBRERO','MARZO','ABRIL','MAYO','JUNIO','JULIO','AGOSTO','SEPTIEMBRE','OCTUBRE','NOVIEMBRE','DICIEMBRE'];
var MESES_CORTO  = ['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];

var ASIGNACION_MENSUAL = 4000;
var ASIGNACION_ANUAL = ASIGNACION_MENSUAL * 12;

var mesTargetNum = d.mesNumeroObjetivo || (new Date().getMonth() + 1);
var anioObjetivo = d.anioObjetivo || new Date().getFullYear();

var staticData = $getWorkflowStaticData('global');
