function clasificarEquipo(codigo, descripcion, esGasolina) {
  var cod = String(codigo || '').toUpperCase();

  // RENDIMIENTOS OFICIALES (confirmados con Gerencia):
  //  - V10 Livianos (gasolina): 1 L = 3.5 Km
  //  - V11 Pesados (gasoil):    1 L = 1.7 Km
  //  - V12 Vacum/transporte:    mantenimiento se sigue midiendo en Km (1.5 Km/L, límite 10.000 Km,
  //                             sin cambios), y ADEMÁS se reporta un dato informativo de horas
  //                             de operación (3 L = 1 hora) vía "divisorHoras".
  //  - V13 Maquinaria pesada:   10 L = 1 hora de trabajo
  if (esGasolina || cod.indexOf('V10-') === 0) {
    return {
      grupo: 'V10',
      nombreGrupo: 'GRUPO V10 — VEHÍCULOS LIVIANOS (GASOLINA)',
      tipoBadge: 'VEHÍCULO LIVIANO (GASOLINA)',
      tipo: 'LIVIANO',
      rendimiento: 3.5,
      limiteMtto: 7000,
      unidadMtto: 'Km',
      combustible: 'GASOLINA'
    };
  } else if (cod.indexOf('V12-') === 0) {
    return {
      grupo: 'V12',
      nombreGrupo: 'GRUPO V12 — EQUIPOS DE TRANSPORTE (VACUM, CISTERNA) (GASOIL)',
      tipoBadge: 'EQUIPO DE TRANSPORTE (GASOIL)',
      tipo: 'ARRASTRE',
      rendimiento: 1.5,
      limiteMtto: 10000,
      unidadMtto: 'Km',
      divisorHoras: 3,
      combustible: 'GASOIL'
    };
  } else if (cod.indexOf('V13-') === 0) {
    return {
      grupo: 'V13',
      nombreGrupo: 'GRUPO V13 — MAQUINARIA PESADA (GASOIL)',
      tipoBadge: 'MAQUINARIA PESADA (GASOIL)',
      tipo: 'MAQUINARIA',
      rendimiento: 10,
      limiteMtto: 350,
      unidadMtto: 'Hrs',
      combustible: 'GASOIL'
    };
  } else {
    return {
      grupo: 'V11',
      nombreGrupo: 'GRUPO V11 — VEHÍCULOS PESADOS (GASOIL)',
      tipoBadge: 'VEHÍCULO PESADO (GASOIL)',
      tipo: 'PESADO',
      rendimiento: 1.7,
      limiteMtto: 10000,
      unidadMtto: 'Km',
      combustible: 'GASOIL'
    };
  }
}

function estimarKmUHoras(litros, clasif) {
  if (!litros || litros <= 0) return 0;
  if (clasif.tipo === 'MAQUINARIA') return Math.round((litros / 10) * 10) / 10;
  return Math.round(litros * clasif.rendimiento);
}

// NUEVO: horas de operación estimadas (solo aplica a grupos con "divisorHoras", hoy V12).
// Es un dato informativo adicional; NO reemplaza el cálculo de mantenimiento en Km.
function estimarHorasSecundarias(litros, clasif) {
  if (!clasif.divisorHoras || !litros || litros <= 0) return null;
  return Math.round((litros / clasif.divisorHoras) * 10) / 10;
}

var equiposMap = {};
var gasoilPorMes = {};
var gasolinaPorMes = {};

var procesarRegistro = function (h, esGasolina) {
  var cant = Number(h.combConsumido) || 0;
  if (cant <= 0) return;

  var info = obtenerInfoEquipo(h.codigo, h.placas, h.descripcion);
  var key = info.codigo !== 'N/D' ? info.codigo : (info.descripcion + '_' + info.placa);

  var fechaReg = h.fecha ? new Date(h.fecha) : null;
  var mesReg = fechaReg ? (fechaReg.getMonth() + 1) : (h.mesNumeroArchivo || mesTargetNum);

  if (mesReg <= mesTargetNum) {
    if (esGasolina) gasolinaPorMes[mesReg] = (gasolinaPorMes[mesReg] || 0) + cant;
    else gasoilPorMes[mesReg] = (gasoilPorMes[mesReg] || 0) + cant;
  }

  if (!equiposMap[key]) {
    equiposMap[key] = {
      codigo: info.codigo,
      descripcion: info.descripcion,
      placa: info.placa,
      esGasolina: esGasolina,
      litrosAnual: 0,
      destinos: []
    };
  }

  if (h.destinoViaje && h.destinoViaje !== '---------' && h.destinoViaje.trim() !== '') {
    var dTrimm = h.destinoViaje.trim();
    if (equiposMap[key].destinos.indexOf(dTrimm) === -1) {
      equiposMap[key].destinos.push(dTrimm);
    }
  }

  var fechaResetStr = resets[info.codigo];
  var fechaReset = fechaResetStr ? new Date(fechaResetStr) : null;
  if (!fechaReset || (fechaReg && fechaReg >= fechaReset)) {
    equiposMap[key].litrosAnual += cant;
  }
};

(d.historialConsumosGasoil || []).forEach(function (h) { procesarRegistro(h, false); });
(d.historialConsumosGasolina || []).forEach(function (h) { procesarRegistro(h, true); });

var semanasPorMes = {};
(d.semanasProcesadas || []).forEach(function (s) {
  var mesSem = s.mesNumeroArchivo;
  if (!mesSem || mesSem > mesTargetNum) return;
  if (!semanasPorMes[mesSem]) semanasPorMes[mesSem] = [];
  if (s.numeroSemana != null && semanasPorMes[mesSem].indexOf(s.numeroSemana) === -1) {
    semanasPorMes[mesSem].push(s.numeroSemana);
  }

  if (!gasoilPorMes[mesSem]) {
    var totSem = (s.filas || []).reduce(function (acc, f) { return acc + (Number(f.total) || 0); }, 0);
    if (totSem > 0) {
      gasoilPorMes[mesSem] = (gasoilPorMes[mesSem] || 0) + totSem;
      (s.filas || []).forEach(function (f) {
        var tot = Number(f.total) || 0;
        if (tot <= 0) return;
        var info = obtenerInfoEquipo(f.codigo, f.placas, f.descripcion);
        var key = info.codigo !== 'N/D' ? info.codigo : (info.descripcion + '_' + info.placa);
        if (!equiposMap[key]) {
          equiposMap[key] = { codigo: info.codigo, descripcion: info.descripcion, placa: info.placa, esGasolina: false, litrosAnual: 0, destinos: [] };
        }
        equiposMap[key].litrosAnual += tot;
      });
    }
  }
});

var mesesConsolidados = [];
for (var m = 1; m <= 12; m++) {
  var procesado = m <= mesTargetNum;
  var gasoilMes = Math.round((gasoilPorMes[m] || 0) * 10) / 10;
  var gasolinaMes = Math.round((gasolinaPorMes[m] || 0) * 10) / 10;
  var totalMes = Math.round((gasoilMes + gasolinaMes) * 10) / 10;
  var pctVsAsignacion = ASIGNACION_MENSUAL > 0 ? Math.round((gasoilMes / ASIGNACION_MENSUAL) * 1000) / 10 : 0;

  mesesConsolidados.push({
    mesNumero: m,
    mesNombre: MESES_NOMBRE[m - 1],
    mesCorto: MESES_CORTO[m - 1],
    procesado: procesado,
    esMesEnCurso: m === mesTargetNum,
    consumoGasoilMes: gasoilMes,
    consumoGasolinaMes: gasolinaMes,
    totalMes: totalMes,
    pctVsAsignacion: pctVsAsignacion,
    excedido: procesado && gasoilMes > ASIGNACION_MENSUAL
  });
}

var totalAnualGasoil = mesesConsolidados.reduce(function (acc, x) { return x.procesado ? acc + x.consumoGasoilMes : acc; }, 0);
var totalAnualGasolina = mesesConsolidados.reduce(function (acc, x) { return x.procesado ? acc + x.consumoGasolinaMes : acc; }, 0);
totalAnualGasoil = Math.round(totalAnualGasoil * 10) / 10;
totalAnualGasolina = Math.round(totalAnualGasolina * 10) / 10;
var totalAnualCombinado = Math.round((totalAnualGasoil + totalAnualGasolina) * 10) / 10;
var saldoAnual = Math.round((ASIGNACION_ANUAL - totalAnualGasoil) * 10) / 10;
var pctConsumidoAnual = ASIGNACION_ANUAL > 0 ? Math.round((totalAnualGasoil / ASIGNACION_ANUAL) * 1000) / 10 : 0;

var listaEquiposAnual = [];
Object.keys(equiposMap).forEach(function (k) {
  var eq = equiposMap[k];
  var clasif = clasificarEquipo(eq.codigo, eq.descripcion, eq.esGasolina);
  var estimadoAnual = estimarKmUHoras(eq.litrosAnual, clasif);
  var porcentajeMtto = Math.min(100, Math.round((estimadoAnual / clasif.limiteMtto) * 100));
  var estimadoHorasAnual = estimarHorasSecundarias(eq.litrosAnual, clasif);

  var alerta = 'OK', claseAlerta = 'ok';
  if (porcentajeMtto >= 90) { alerta = 'CRÍTICO'; claseAlerta = 'critico'; }
  else if (porcentajeMtto >= 75) { alerta = 'ADVERTENCIA'; claseAlerta = 'advertencia'; }

  listaEquiposAnual.push({
    codigo: eq.codigo,
    descripcion: eq.descripcion,
    placa: eq.placa,
    grupo: clasif.grupo,
    nombreGrupo: clasif.nombreGrupo,
    tipoBadge: clasif.tipoBadge,
    combustible: clasif.combustible,
    tipo: clasif.tipo,
    totalLitrosAnual: Math.round(eq.litrosAnual * 10) / 10,
    estimadoAnual: estimadoAnual,
    estimadoHorasAnual: estimadoHorasAnual,
    limiteMtto: clasif.limiteMtto,
    unidadMtto: clasif.unidadMtto,
    porcentajeMtto: porcentajeMtto,
    alerta: alerta,
    claseAlerta: claseAlerta,
    destino: eq.destinos.length ? eq.destinos.join(' / ') : 'BASE RX'
  });
});

listaEquiposAnual.sort(function (a, b) { return b.porcentajeMtto - a.porcentajeMtto; });

var top10EquiposAnual = listaEquiposAnual.slice().sort(function (a, b) {
  return b.totalLitrosAnual - a.totalLitrosAnual;
}).slice(0, 10);

// NUEVO: acota las alertas de calidad de datos a los meses ya procesados del año
// (1..mesTargetNum), igual criterio que el resto de este nodo, para no arrastrar
// avisos del mes siguiente que solo se cargó para resolver semanas cruzadas.
function parsearMesDeHoja(nombreHoja) {
  var partes = String(nombreHoja || '').split('-');
  return partes.length === 3 ? parseInt(partes[1], 10) : null;
}
var alertasCalidadDatosAnual = (d.alertasCalidadDatos || []).filter(function (a) {
  var mes = parsearMesDeHoja(a.fecha);
  return mes && mes <= mesTargetNum;
});

return [{
  json: Object.assign({}, d, {
    modo: 'informe_anual',
    tipoReporte: 'ANUAL',
    anioObjetivo: anioObjetivo,
    mesNumeroObjetivo: mesTargetNum,
    mesObjetivoNombre: MESES_NOMBRE[mesTargetNum - 1],
    asignacionMensual: ASIGNACION_MENSUAL,
    asignacionAnual: ASIGNACION_ANUAL,
    mesesConsolidados: mesesConsolidados,
    totalAnualGasoil: totalAnualGasoil,
    totalAnualGasolina: totalAnualGasolina,
    totalAnualCombinado: totalAnualCombinado,
    saldoAnual: saldoAnual,
    pctConsumidoAnual: pctConsumidoAnual,
    equiposAnual: listaEquiposAnual,
    top10EquiposAnual: top10EquiposAnual,
    alertasCalidadDatos: alertasCalidadDatosAnual
  })
}];

// ======================================================
// ROYAL EXPRESS C.A. - EVALUAR ALERTAS DE MANTENIMIENTO (FORMATO DE KM CORREGIDO)
// ======================================================
var d = $input.first().json;

var staticData = $getWorkflowStaticData('global');
var resets = staticData.resetPorEquipo || {};
if (!staticData.lastAlertedMaintenance) staticData.lastAlertedMaintenance = {};

var catalogoReal = {};
try {
  var catData = $('Parsear Catalogo Equipos (DATA)').first().json;
  catalogoReal = (catData && catData.catalogoEquipos) ? catData.catalogoEquipos : {};
} catch (e) {}

function normalizarPlaca(p) {
  return String(p || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
}

function obtenerInfoEquipo(codigo, placaFila, descFila) {
  var cod = String(codigo || '').toUpperCase().trim();
  var placa = placaFila && String(placaFila).trim() !== '---------' ? String(placaFila).trim() : '';
  var desc = descFila || '';

  if (cod && catalogoReal[cod]) {
    if (!placa || placa === '---------') placa = catalogoReal[cod].placa || '';
    if (!desc) desc = catalogoReal[cod].descripcion || '';
  } else if (!cod && placa) {
    var pNorm = normalizarPlaca(placa);
    var matchCod = Object.keys(catalogoReal).find(function(k) {
      return normalizarPlaca(catalogoReal[k].placa) === pNorm;
    });
    if (matchCod) {
      cod = matchCod;
      if (!desc) desc = catalogoReal[cod].descripcion || '';
    }
  }
  return { codigo: cod || 'N/D', placa: placa || 'N/A', descripcion: desc || 'Sin descripción' };
}

function clasificarEquipo(codigo, esTablaGasolina) {
  var cod = String(codigo || '').toUpperCase();
  if (esTablaGasolina || cod.indexOf('V10-') === 0) {
    return { grupo: 'V10', tituloGrupo: '🚗 VEHÍCULOS LIVIANOS (GASOLINA)', tipo: 'LIVIANO', rendimiento: 3.5, limiteMtto: 7000, unidadMtto: 'Km' };
  } else if (cod.indexOf('V12-') === 0) {
    return { grupo: 'V12', tituloGrupo: '🚚 EQUIPOS DE TRANSPORTE / VACUM (GASOIL)', tipo: 'ARRASTRE', rendimiento: 1.5, limiteMtto: 10000, unidadMtto: 'Km' };
  } else if (cod.indexOf('V13-') === 0) {
    return { grupo: 'V13', tituloGrupo: '🚜 MAQUINARIA PESADA (GASOIL)', tipo: 'MAQUINARIA', rendimiento: 10, limiteMtto: 350, unidadMtto: 'Hrs' };
  }
  return { grupo: 'V11', tituloGrupo: '🚛 VEHÍCULOS PESADOS (GASOIL)', tipo: 'PESADO', rendimiento: 1.7, limiteMtto: 10000, unidadMtto: 'Km' };
}

function estimarKmUHoras(litros, clasif) {
  if (!litros || litros <= 0) return 0;
  if (clasif.tipo === 'MAQUINARIA') return Math.round((litros / 10) * 10) / 10;
  return Math.round(litros * clasif.rendimiento);
}

// FORMATEADOR DE MILES CORREGIDO (10.382 / 10.000 / 7.592)
function formatMiles(n) {
  var num = Math.round(Number(n) || 0);
  var signo = num < 0 ? '-' : '';
  var absStr = String(Math.abs(num));
  var formatted = absStr.replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return signo + formatted;
}

function textoAccionFamilia(grupo, codigo) {
  if (grupo === 'V10') return 'Planificar según las rutinas de mantenimiento de los vehículos livianos /reset ' + codigo;
  if (grupo === 'V12') return 'Planificar según las rutinas de mantenimiento de los equipos de transporte /reset ' + codigo;
  if (grupo === 'V13') return 'Planificar según las rutinas de mantenimiento de las maquinarias pesadas /reset ' + codigo;
  return 'Planificar según las rutinas de mantenimiento de los vehículos pesados /reset ' + codigo;
}

var equiposMap = {};

function procesarRegistro(h, esGasolina) {
  var cant = Number(h.combConsumido) || 0;
  if (cant <= 0) return;

  var info = obtenerInfoEquipo(h.codigo, h.placas, h.descripcion);
  var key = info.codigo !== 'N/D' ? info.codigo : (info.descripcion + '_' + info.placa);

  if (!equiposMap[key]) {
    equiposMap[key] = { codigo: info.codigo, descripcion: info.descripcion, placa: info.placa, esGasolina: esGasolina, litrosAcumulados: 0 };
  }

  var fechaReg = h.fecha ? new Date(h.fecha) : null;
  var fechaResetStr = resets[info.codigo];
  var fechaReset = fechaResetStr ? new Date(fechaResetStr) : null;

  if (!fechaReset || (fechaReg && fechaReg >= fechaReset)) {
    equiposMap[key].litrosAcumulados += cant;
  }
}

(d.historialConsumosGasoil || []).forEach(function(h) { procesarRegistro(h, false); });
(d.historialConsumosGasolina || []).forEach(function(h) { procesarRegistro(h, true); });

var listaRojo = [];
var listaAmarillo = [];
var estadoActual = {};

Object.keys(equiposMap).forEach(function(k) {
  var eq = equiposMap[k];
  if (eq.codigo === 'N/D') return;

  var clasif = clasificarEquipo(eq.codigo, eq.esGasolina);
  var acumulado = estimarKmUHoras(eq.litrosAcumulados, clasif);
  var faltan = clasif.limiteMtto - acumulado;
  var pct = Math.round((acumulado / clasif.limiteMtto) * 1000) / 10;
  var margenAmarillo = clasif.tipo === 'MAQUINARIA' ? 25 : 500;

  var fila = {
    codigo: eq.codigo,
    descripcion: eq.descripcion,
    placa: eq.placa,
    grupo: clasif.grupo,
    tituloGrupo: clasif.tituloGrupo,
    tipo: clasif.tipo,
    acumulado: acumulado,
    limiteMtto: clasif.limiteMtto,
    unidadMtto: clasif.unidadMtto,
    pct: pct,
    faltan: faltan
  };

  if (acumulado >= clasif.limiteMtto) {
    listaRojo.push(fila);
    estadoActual[eq.codigo] = { estado: 'ROJO', acumulado: acumulado };
  } else if (faltan <= margenAmarillo) {
    listaAmarillo.push(fila);
    estadoActual[eq.codigo] = { estado: 'AMARILLO', acumulado: acumulado };
  }
});

listaRojo.sort(function(a, b) { return b.pct - a.pct; });
listaAmarillo.sort(function(a, b) { return b.pct - a.pct; });

// Anti-spam
var previo = staticData.lastAlertedMaintenance || {};
var hayNovedad = false;

listaRojo.concat(listaAmarillo).forEach(function(f) {
  var anterior = previo[f.codigo];
  if (!anterior) { hayNovedad = true; return; }
  if (anterior.estado === 'AMARILLO' && estadoActual[f.codigo].estado === 'ROJO') { hayNovedad = true; return; }
});

staticData.lastAlertedMaintenance = estadoActual;

if (!hayNovedad || (listaRojo.length === 0 && listaAmarillo.length === 0)) {
  return [{ json: { sendAlert: false, message: '' } }];
}

function bloqueEquipo(f, esRojo) {
  var acumuladoFmt = f.tipo === 'MAQUINARIA' ? f.acumulado.toFixed(1).replace('.', ',') : formatMiles(f.acumulado);
  var limiteFmt = f.tipo === 'MAQUINARIA' ? f.limiteMtto.toFixed(1).replace('.', ',') : formatMiles(f.limiteMtto);
  var unidad = f.unidadMtto;
  var lineas = [];
  var nombre = f.codigo + ' — ' + f.descripcion + (f.placa && f.placa !== 'N/A' ? ' (' + f.placa + ')' : '');
  lineas.push((esRojo ? '🔴' : '🟢') + ' <b>' + nombre + '</b>');
  lineas.push('• Acumulado: <b>' + acumuladoFmt + ' ' + unidad + '</b> / Límite: ' + limiteFmt + ' ' + unidad + ' (' + f.pct.toFixed(1) + '%)');

  var accionTxt = textoAccionFamilia(f.grupo, f.codigo);
  lineas.push('• <b>Acción: ' + accionTxt + '</b>');

  return lineas.join('\n');
}

var ORDEN_GRUPOS = [
  { id: 'V11', titulo: '🚛 VEHÍCULOS PESADOS (GASOIL)' },
  { id: 'V10', titulo: '🚗 VEHÍCULOS LIVIANOS (GASOLINA)' },
  { id: 'V12', titulo: '🚚 EQUIPOS DE TRANSPORTE / VACUM (GASOIL)' },
  { id: 'V13', titulo: '🚜 MAQUINARIA PESADA (GASOIL)' }
];

function renderSeccionPorGrupos(items, esRojo) {
  var bloques = [];
  ORDEN_GRUPOS.forEach(function(grp) {
    var itemsDelGrupo = items.filter(function(it) { return it.grupo === grp.id; });
    if (itemsDelGrupo.length === 0) return;
    var subBloque = ['<b>' + grp.titulo + ':</b>'];
    itemsDelGrupo.forEach(function(it) { subBloque.push(bloqueEquipo(it, esRojo)); });
    bloques.push(subBloque.join('\n'));
  });
  return bloques.join('\n\n');
}

var partes = [];
partes.push('🚨 <b>ROYAL EXPRESS C.A. — ALERTA DE MANTENIMIENTO</b> 🚨');

if (listaRojo.length) {
  partes.push('🛑 <b>Se detectaron equipos que sobrepasaron el límite establecido por el departamento de mantenimiento:</b>\n\n' + renderSeccionPorGrupos(listaRojo, true));
}

if (listaRojo.length && listaAmarillo.length) {
  partes.push('──────────────────────────────');
}

if (listaAmarillo.length) {
  partes.push('⚠️ <b>Se detectaron equipos que se acercan al límite establecido por el departamento de mantenimiento:</b>\n\n' + renderSeccionPorGrupos(listaAmarillo, false));
}

partes.push('──────────────────────────────');
partes.push('👨‍💻 <i>Sistema desarrollado por: Ing. Vladimir Marcano</i>');

var mensaje = partes.join('\n\n');

// GENERAR BOTONES INLINE CON CÍRCULOS ROJOS Y VERDES (1-CLIC)
var botones = [];
var filaBotones = [];

listaRojo.forEach(function(eq, idx) {
  filaBotones.push({ text: '🔴 Reset ' + eq.codigo, callback_data: '/reset ' + eq.codigo });
  if (filaBotones.length === 2 || idx === listaRojo.length - 1) {
    botones.push(filaBotones);
    filaBotones = [];
  }
});

filaBotones = [];
listaAmarillo.forEach(function(eq, idx) {
  filaBotones.push({ text: '🟢 Reset ' + eq.codigo, callback_data: '/reset ' + eq.codigo });
  if (filaBotones.length === 2 || idx === listaAmarillo.length - 1) {
    botones.push(filaBotones);
    filaBotones = [];
  }
});

var reply_markup = botones.length ? { inline_keyboard: botones } : null;

return [{
  json: {
    sendAlert: true,
    message: mensaje,
    reply_markup: reply_markup,
    chatId: d.chatId || '5016875501'
  }
}];
